// Generates src/buildInfo.ts with the latest git tag (stripped of `v` prefix)
// and short SHA. Runs before `expo run:android` / `expo run:ios` via npm
// scripts. The generated file is gitignored — every build regenerates it.
//
// We do this instead of EXPO_PUBLIC_* env vars because Metro's bundle cache
// can hold a stale bundle across builds, ignoring a changed env var. Writing
// a real TS file forces Metro to pick up the new content via normal source
// invalidation.
import { execSync } from "child_process";
import { writeFileSync } from "fs";
import { fileURLToPath } from "url";
import { dirname, join } from "path";

const __dirname = dirname(fileURLToPath(import.meta.url));
const outPath = join(__dirname, "..", "src", "buildInfo.ts");

function safe(cmd, fallback) {
  try {
    return execSync(cmd, { stdio: ["ignore", "pipe", "ignore"] }).toString().trim();
  } catch {
    return fallback;
  }
}

const version = safe("git describe --tags --abbrev=0", "0.0.0").replace(/^v/, "");
const hash = safe("git rev-parse --short HEAD", "");

const contents = `// AUTO-GENERATED by scripts/write-build-info.mjs — do not edit.
// Regenerated on every \`npm run android\` / \`npm run ios\`.
export const BUILD_VERSION = "${version}";
export const BUILD_HASH = "${hash}";
`;

writeFileSync(outPath, contents);
console.log(`[build-info] wrote ${outPath}: ${version}${hash ? ` (${hash})` : ""}`);
